SELECT m.code,m.quantity AS qty,printf('%.3f',m.price_HKD) AS p15,printf('%.3f',z.price_HKD) AS close,printf('%.2f',m.quantity*z.price_HKD*0.86482) AS value, printf('%+.5f',n.amount_CNY-n.quantity*z.price_HKD*0.86482) AS next_error FROM minute_quotes m JOIN minute_quotes z ON m.code=z.code AND m.date=z.date AND z.time='16:08' JOIN next_pcf n ON n.code=m.code WHERE m.time='15:00' ORDER BY m.code;
